// src/utils/naming-conventions.ts
var toKebabCase = (str) => {
  return str.split(" ").map((part, index) => {
    if (index === 0) {
      return part.toLowerCase();
    }
    return part.charAt(0).toLowerCase() + part.slice(1);
  }).join("-");
};
var toPascalCase = (str) => {
  const words = str.match(/[a-z0-9]+/gi) || [];
  return words.map(
    (word) => word.charAt(0).toUpperCase() + word.substring(1).toLowerCase()
  ).join("");
};

// src/utils/find-metadata.ts
import {
  networks,
  tokens,
  wallets,
  exchanges
} from "@web3icons/common";
var findMetadata = (metadata, searchCriteria) => {
  return metadata.find((item) => {
    return Object.keys(searchCriteria).some((key) => {
      const value = searchCriteria[key];
      if (value === void 0)
        return false;
      if (typeof value === "object") {
        return Object.entries(value).every(
          ([k, v]) => item[key]?.[k] === v
        );
      }
      if (typeof value === "string") {
        const itemValue = item[key];
        return typeof itemValue === "string" && itemValue.toLowerCase() === value.toLowerCase();
      } else {
        return item[key] === value;
      }
    });
  });
};
var findWallet = ({
  wallet
}) => {
  return findMetadata(wallets, { id: toKebabCase(wallet), name: wallet });
};
var findToken = ({
  symbol,
  address,
  network
}) => {
  if (symbol) {
    return findMetadata(tokens, { symbol });
  } else if (address && network) {
    return findMetadata(tokens, { addresses: { [network]: address } });
  }
  return void 0;
};
var findNetwork = ({
  network,
  chainId
}) => {
  if (network) {
    return findMetadata(networks, {
      id: toKebabCase(network),
      name: network,
      shortName: network
    });
  }
  if (chainId) {
    return findMetadata(networks, { chainId });
  }
  return void 0;
};
var findExchange = ({
  name,
  id
}) => {
  if (id) {
    return findMetadata(exchanges, { id: toKebabCase(id), name: id });
  }
  if (name) {
    return findMetadata(exchanges, { id: toKebabCase(name), name });
  }
};

